CREATE TABLE KIMLIK (PS INTEGER NOT NULL PRIMARY KEY, PKNO VARCHAR(5), GRUP INTEGER, SERVIS INTEGER, SIRKET INTEGER, BOLUM INTEGER, DURUM INTEGER, GOREV INTEGER, IGTARIH TIMESTAMP, ICTARIH TIMESTAMP, MAAS DOUBLE PRECISION, SSKNO VARCHAR(30), UKNO VARCHAR(11), AD VARCHAR(50), SOYAD VARCHAR(50), SICILNO VARCHAR(10), ESDRM SMALLINT NOT NULL);
CREATE TABLE DURUM (KOD INTEGER NOT NULL PRIMARY KEY, AD VARCHAR(30));
CREATE TABLE GRUP (KOD INTEGER NOT NULL PRIMARY KEY, AD VARCHAR(30));
CREATE TABLE FIRMA (KOD INTEGER NOT NULL PRIMARY KEY, AD VARCHAR(50));
CREATE TABLE BORDRO (KOD INTEGER NOT NULL PRIMARY KEY, AD VARCHAR(30), KAD VARCHAR(7));
CREATE TABLE DONEM (KOD INTEGER NOT NULL PRIMARY KEY, AD VARCHAR(30), BASTAR TIMESTAMP, BITTAR TIMESTAMP);
CREATE TABLE UCRETLER (PKNO VARCHAR(5), BASTAR TIMESTAMP, BITTAR TIMESTAMP, DONEM INTEGER, DEVS VARCHAR(7), DEVG DOUBLE PRECISION, ERS VARCHAR(7), GECS VARCHAR(7), EKS VARCHAR(7), NCSAAT VARCHAR(7), NCGUN DOUBLE PRECISION, FMSAAT VARCHAR(7), TOPEKS VARCHAR(7), SSKG INTEGER, SAAT1 VARCHAR(7), GUN1 DOUBLE PRECISION, SAAT2 VARCHAR(7), GUN2 DOUBLE PRECISION);
CREATE TABLE OZELIZIN (PKNO VARCHAR(5), TARIH TIMESTAMP, TIP VARCHAR(10), MAZERET VARCHAR(100));
COMMIT;
